APC.nearest.source:
def nearest (s : K → X) (x : X) : K :=
  Classical.choose (Finset.exists_min_image Finset.univ (fun j => dist x (s j))
    Finset.univ_nonempty)

APC.dependentKernelWeight.source:
def dependentKernelWeight {Ω : Type*} {Λ : Ω → Type*}
    (p : Ω → ℝ) (q : (ω : Ω) → Λ ω → ℝ) (sample : Sigma Λ) : ℝ :=
  p sample.1*q sample.1 sample.2

APC.EuclideanIteration.probability.source:
def probability {I : Type*} [Fintype I] (c : Cloud I X) (proxy : K → X) : I → ℝ :=
  sensitivityProbability c.weights (fun i => pointCost proxy (c.points i))
    (fun i => nearest proxy (c.points i))

APC.EuclideanIteration.sample.source:
def sample {I : Type*} [Fintype I] (c : Cloud I X) (proxy : K → X)
    (m : ℕ) (z : Draws I m) : Cloud (Fin m) X :=
  ⟨sampledPoints c.points m z, sampledWeights c.weights (probability c proxy) m z⟩

APC.euclideanOptimal.source:
def euclideanOptimal (x : I → E) (w : I → ℝ) : K → E :=
  assignmentCenters x w (Classical.choose (Finset.exists_min_image Finset.univ
    (fun a : I → K=>cost x w (assignmentCenters x w a)) Finset.univ_nonempty))

APC.euclideanSizeEnvelope.source:
def euclideanSizeEnvelope (k : ℕ) (a c C : ℝ) (p q : ℕ) (ε δ : ℝ) : ℝ :=
  10000*(23+22*a)^2*(48+(1+c)*(4*(64*a+8*a^2)))*(k:ℝ)*
    polynomialLogBudget k C p q ε δ/ε^3+2

APC.geometricLift.source:
def geometricLift (x : I → E) (w : I → ℝ) (hw : ∀ i, 0 ≤ w i)
    (m : ℕ) (hm : 0 < m) (s : K → E) : K → E :=
  Classical.choose (exists_structured_lift x w hw s m hm)

APC.vectorImportance.source:
def vectorImportance (p : I → ℝ) (v : I → E) (m : ℕ) (z : Draws I m) : E :=
  (m:ℝ)⁻¹ • drawSum (fun i=>(p i)⁻¹ • v i) m z

