APC.MetricIteration.supportSearch.source:
def supportSearch (c : Cloud I X) : K → I :=
  Classical.choose (Finset.exists_min_image Finset.univ
    (fun f : K → I=>cost c.points c.weights (fun j=>c.points (f j))) Finset.univ_nonempty)

APC.MetricIteration.subsetOutput.source:
def subsetOutput {m : ℕ} [NeZero m] (c : Cloud (Fin m) X)
    (hkm : Fintype.card K≤m) : K → X :=
  subsetSearchCenters c (by simpa using hkm)

APC.partitionResidual.source:
def partitionResidual (x : I → X) (a : I → K) (proxy s : K → X)
    (close : K → Prop) (i : I) : ℝ :=
  if close (a i) then pointCost s (x i)-pointCost s (proxy (a i)) else 0

APC.liftingTrialsLaw.source:
def liftingTrialsLaw (x : I → E) (w : I → ℝ) (s : K → E) (m r : ℕ) :
    LiftOutcome I K m r → ℝ :=
  productWeight (fun j=>meanTrialsWeight (liftingWeights x w s j) m r)

APC.MetricIteration.subsetTuple.source:
def subsetTuple (S : Finset I) : K → I :=
  if hS : S.card=Fintype.card K then fun j=>(subsetEquiv S hS j).val
  else fun _=>Classical.arbitrary I

APC.Approximate.source:
def Approximate {Solution : Type*} (cost : Solution → ℝ)
    (α : ℝ) (s : Solution) : Prop :=
  ∀ c, cost s ≤ α * cost c
